    'NotificationExtraDesc'               => '邮件通知扩展功能使 SimpleRisk 能够在风险提交、修改或进行其他操作时发送电子邮件通知。该扩展功能还可以添加为定时脚本，以便在风险准备好进行管理层审核时发送例行提醒。在 SimpleRisk Core 产品中，如果没有此扩展功能，则不会向工具外部发送任何通知。',
    'VulnerabilityManagementExtraDesc'    => '漏洞管理扩展使客户能够将其 SimpleRisk 实例与 Qualys、Tenable.io 或 Rapid7 Nexpose/InsightVM 集成,并将资产和漏洞数据导入 SimpleRisk。之后,您可以选择要覆盖的站点,确定应导入哪些漏洞评分,并对哪些漏洞转化为风险进行分类处理以便跟踪。',
    'IncidentManagementExtraDesc'         => '事件管理扩展基于 NIST 800-61《计算机安全事件处理指南》,在 SimpleRisk 系统内提供事件管理功能。',

