    'UnlockImportExportLink' => '查看它的功能',
    'UnlockActivateImportExportNote' => '已安装导入导出扩展程序，但未启用。',
    'UnlockActivateImportExportLink' => '启用',
    // Shown instead of any of the above to a user who is not an administrator:
